 function handleCommand(item:CommandItem){
  setError('');
  if(item.kind==='page'){navigate(item.page);return}
  if(item.kind==='action'){
   if(!editable||busy)return;
   switch(item.action){
    case 'income':quickTransaction(true);return;
    case 'expense':quickTransaction(false);return;
    case 'transaction':navigate('Transaktioner');editTransaction();return;
    case 'plan':navigate('Översikt');setBudgetPlanRequest(n=>n+1);return;
    case 'revenue-source':navigate('Intäkter');editRevenueSource();return;
    case 'loan':navigate('Skulder');editDebt();return;
    case 'goal':navigate('Sparande');editGoal();return;
    case 'import':navigate('Transaktioner');requestAnimationFrame(()=>fileRef.current?.click());return;
   }
  }
  if(!data||item.kind!=='record')return;
  const canEdit=editable&&!busy;
  switch(item.recordKind){
   case 'transactions':{const record=data.transactions.find(x=>x.id===item.recordId);if(!record)return;setDateRange(monthRange(record.date));setQuery(record.description);setFilter('Alla');setCategoryFilter('');navigate('Transaktioner');if(canEdit)editTransaction(record);break}
   case 'revenueSources':{const record=data.revenueSources?.find(x=>x.id===item.recordId);navigate('Intäkter');if(record&&canEdit)editRevenueSource(record);break}
   case 'debts':{const record=data.debts.find(x=>x.id===item.recordId);navigate('Skulder');if(record&&canEdit)editDebt(record);break}
   case 'goals':{const record=data.goals.find(x=>x.id===item.recordId);navigate('Sparande');if(record&&canEdit)editGoal(record);break}
   case 'incomes':{const record=data.incomes.find(x=>x.id===item.recordId);navigate('Översikt');setBudgetPlanRequest(n=>n+1);if(record&&canEdit)editIncome(record);break}
   case 'expenses':{const record=data.expenses.find(x=>x.id===item.recordId);navigate('Översikt');setBudgetPlanRequest(n=>n+1);if(record&&canEdit)editExpense(record);break}
   case 'creditors':setCreditorCaseId(item.recordId);setCreditorCaseRequest(n=>n+1);navigate('Borgenärer');break;
  }
 }
